-- Initial schema. For fresh installs, backend/schema.sql is canonical.
-- Migration runner applies this SQL file to the configured database.
CREATE TABLE IF NOT EXISTS hubs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,qr_token CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS departments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,hub_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,qr_token CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_department_hub_name(hub_id,name),CONSTRAINT fk_dept_hub FOREIGN KEY(hub_id) REFERENCES hubs(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS employees (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id_ciphertext TEXT NOT NULL,employee_id_iv CHAR(24) NOT NULL,employee_id_tag CHAR(32) NOT NULL,employee_id_bidx CHAR(64) NOT NULL UNIQUE,full_name VARCHAR(220) NOT NULL,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',hub_id BIGINT UNSIGNED NOT NULL,department_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_employee_hub FOREIGN KEY(hub_id) REFERENCES hubs(id),CONSTRAINT fk_employee_dept FOREIGN KEY(department_id) REFERENCES departments(id),INDEX idx_employee_name(full_name),INDEX idx_employee_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role ENUM('Admin','Superadmin') NOT NULL,login_ciphertext TEXT NOT NULL,login_iv CHAR(24) NOT NULL,login_tag CHAR(32) NOT NULL,login_bidx CHAR(64) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,employee_id BIGINT UNSIGNED NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_account_employee FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL,INDEX idx_account_role_active(role,active)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaints (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,context_hub_id BIGINT UNSIGNED NOT NULL,context_department_id BIGINT UNSIGNED NULL,complainant_employee_bidx CHAR(64) NOT NULL,complainant_employee_ciphertext TEXT NOT NULL,complainant_employee_iv CHAR(24) NOT NULL,complainant_employee_tag CHAR(32) NOT NULL,severity ENUM('Low','Medium','High','Critical') NOT NULL,subject_ciphertext TEXT NULL,subject_iv CHAR(24) NULL,subject_tag CHAR(32) NULL,message_ciphertext LONGTEXT NOT NULL,message_iv CHAR(24) NOT NULL,message_tag CHAR(32) NOT NULL,created_by_account_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_complaint_hub FOREIGN KEY(context_hub_id) REFERENCES hubs(id),CONSTRAINT fk_complaint_dept FOREIGN KEY(context_department_id) REFERENCES departments(id),CONSTRAINT fk_complaint_creator FOREIGN KEY(created_by_account_id) REFERENCES accounts(id) ON DELETE SET NULL,INDEX idx_complaint_created(created_at),INDEX idx_complaint_severity(severity),INDEX idx_complaint_complainant_day(complainant_employee_bidx,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaint_reported_employees (complaint_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(complaint_id,employee_id),INDEX idx_reported_employee(employee_id,complaint_id),CONSTRAINT fk_reported_complaint FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE,CONSTRAINT fk_reported_employee FOREIGN KEY(employee_id) REFERENCES employees(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS access_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,account_id BIGINT UNSIGNED NULL,role VARCHAR(30) NULL,login_bidx CHAR(64) NULL,event ENUM('login_success','login_failure','logout','otp_failure') NOT NULL,ip_address VARCHAR(64) NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_access_created(created_at),INDEX idx_access_account(account_id),CONSTRAINT fk_log_account FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS superadmin_otps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,account_id BIGINT UNSIGNED NOT NULL,otp_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,consumed_at DATETIME NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_otp_account_expiry(account_id,expires_at),CONSTRAINT fk_otp_account FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB;
